CREATE OR REPLACE FUNCTION public.att_punch(p_direction text, p_lat double precision, p_lng double precision, p_accuracy integer, p_device text, p_photo_path text, p_reason text, p_source text DEFAULT 'app'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_staff  uuid := public.att_my_staff_id();
  v_local  timestamp := now() AT TIME ZONE 'Asia/Kuala_Lumpur';
  v_pol    public.att_policy%ROWTYPE;
  v_day    date;
  v_loc    uuid;
  v_dist   integer;
  v_radius integer;
  v_inside boolean;
  v_id     uuid;
BEGIN
  IF v_staff IS NULL THEN RAISE EXCEPTION 'Punching needs a staff record linked to this login.' USING ERRCODE = '42501'; END IF;
  IF p_direction NOT IN ('in', 'out') THEN RAISE EXCEPTION 'IN or OUT.'; END IF;
  IF p_photo_path IS NOT NULL AND (NOT starts_with(p_photo_path, 'punch/' || auth.uid()::text || '/') OR strpos(p_photo_path, '..') > 0
       OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'attendance' AND o.name = p_photo_path)) THEN
    RAISE EXCEPTION 'The photo was not filed — take it again.' USING ERRCODE = '22023';
  END IF;
  SELECT * INTO v_pol FROM public.att_policy WHERE effective_from <= v_local::date ORDER BY effective_from DESC LIMIT 1;
  v_day := CASE WHEN v_pol.id IS NOT NULL AND to_char(v_local, 'HH24:MI') < v_pol.cutover THEN v_local::date - 1 ELSE v_local::date END;
  IF p_lat IS NOT NULL AND p_lng IS NOT NULL THEN
    SELECT l.id, l.radius_m,
           round(6371000 * 2 * asin(sqrt(power(sin(radians(l.lat - p_lat) / 2), 2)
                 + cos(radians(p_lat)) * cos(radians(l.lat)) * power(sin(radians(l.lng - p_lng) / 2), 2))))::integer AS d
      INTO v_loc, v_radius, v_dist
      FROM public.att_locations l
     WHERE l.deleted_at IS NULL AND l.lat IS NOT NULL AND l.lng IS NOT NULL
     ORDER BY 3 LIMIT 1;
    v_inside := CASE WHEN v_loc IS NULL THEN NULL ELSE v_dist <= v_radius END;
  END IF;
  IF v_inside IS FALSE AND v_pol.fence_mode = 'refuse' THEN
    RAISE EXCEPTION 'You are outside every allowed location.';
  END IF;
  INSERT INTO public.att_punches (staff_id, work_day, direction, source, lat, lng, accuracy_m, location_id, distance_m, inside_fence,
         device, photo_path, reason)
  VALUES (v_staff, v_day, p_direction, CASE WHEN p_source IN ('app', 'web') THEN p_source ELSE 'app' END, p_lat, p_lng, p_accuracy,
          v_loc, v_dist, v_inside, left(coalesce(p_device, ''), 120), p_photo_path, left(btrim(coalesce(p_reason, '')), 200))
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('id', v_id, 'day', v_day, 'inside', v_inside, 'distance', v_dist);
END
$function$

CREATE OR REPLACE FUNCTION public.att_request_attach(p_request uuid, p_path text, p_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_r public.att_requests%ROWTYPE;
BEGIN
  SELECT * INTO v_r FROM public.att_requests WHERE id = p_request FOR UPDATE;
  IF NOT FOUND OR v_r.status <> 'pending' THEN
    RAISE EXCEPTION 'This request is no longer waiting.';
  END IF;
  IF v_r.staff_id IS DISTINCT FROM public.att_my_staff_id() THEN
    PERFORM public.att_need(ARRAY['attendance.create'], 'Filing a file for somebody else needs Attendance · Create.');
  END IF;
  IF auth.uid() IS NULL OR p_path IS NULL OR NOT starts_with(p_path, 'request/' || auth.uid()::text || '/') OR strpos(p_path, '..') > 0
     OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'attendance' AND o.name = p_path) THEN
    RAISE EXCEPTION 'The file was not filed — send it again.' USING ERRCODE = '22023';
  END IF;
  UPDATE public.att_requests
     SET attachment_path = p_path, attachment_name = left(coalesce(nullif(btrim(p_name), ''), 'Attachment'), 200)
   WHERE id = p_request;
  PERFORM public.att_event('request', p_request::text, v_r.staff_id, 'File attached', left(coalesce(btrim(p_name), ''), 200));
  RETURN jsonb_build_object('id', p_request);
END
$function$

CREATE OR REPLACE FUNCTION public.guest_link_hire(p_code text, p_subsidiary uuid, p_name text, p_answers jsonb, p_attachment_path text, p_attachment_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  g      public.guest_link%ROWTYPE;
  v_sub  public.guest_link_subsidiaries%ROWTYPE;
  v_name text := btrim(coalesce(p_name, ''));
  v_miss text[] := '{}';
  v_path text := nullif(btrim(coalesce(p_attachment_path, '')), '');
  v_file text := nullif(btrim(coalesce(p_attachment_name, '')), '');
  v_id   text;
BEGIN
  SELECT * INTO g FROM public.guest_link_open(p_code, 'hiring');
  IF NOT FOUND THEN
    RAISE EXCEPTION 'This link is closed.' USING ERRCODE = '42501';
  END IF;
  IF to_regprocedure('public.hiring_file_guest_request(text, text, text, text, jsonb, text, text)') IS NULL THEN
    RAISE EXCEPTION 'Requests are not open yet.';
  END IF;
  -- At most 20 requests an hour come in through the link (2026-10-11, review M1).
  IF (SELECT count(*) FROM public.hiring_requests r
       WHERE r.source = 'guest' AND r.submitted_at > now() - interval '1 hour') >= 20 THEN
    RAISE EXCEPTION 'Too many requests from the guest link just now. Try again later.';
  END IF;
  SELECT * INTO v_sub FROM public.guest_link_subsidiaries WHERE id = p_subsidiary AND deleted_at IS NULL;
  IF NOT FOUND THEN v_miss := v_miss || 'Company'::text; END IF;
  IF v_name = '' THEN v_miss := v_miss || 'Your name'::text; END IF;
  IF cardinality(v_miss) > 0 THEN
    RAISE EXCEPTION 'Fill in %.', array_to_string(v_miss, ', ');
  END IF;
  IF length(v_name) > 80 THEN RAISE EXCEPTION 'Keep your name under 80 characters.'; END IF;
  -- The role's department is one of the company's own (2026-10-12, the user): Admin › Guest Link ›
  -- Subsidiaries & departments, as Book a meeting room asks it — never Hiring › Form settings'
  -- choices, which are HQ's. A company with none listed takes the guest's own words.
  IF cardinality(v_sub.departments) > 0 AND btrim(coalesce(p_answers ->> 'dept', '')) <> ''
     AND NOT (btrim(p_answers ->> 'dept') = ANY (v_sub.departments)) THEN
    RAISE EXCEPTION 'Pick a department from %''s list — reload the page if it has changed.', v_sub.name;
  END IF;
  IF length(btrim(coalesce(p_answers ->> 'dept', ''))) > 60 THEN
    RAISE EXCEPTION 'Keep the department under 60 characters.';
  END IF;
  IF v_path IS NOT NULL THEN
    -- Only a file this link's own guests could have put there, and only one that is there.
    IF v_path !~ ('^guest/' || g.code || '/[0-9a-f-]{36}\.(pdf|doc|docx|png|jpe?g|webp)$') THEN
      RAISE EXCEPTION 'Attach the file again.';
    END IF;
    IF to_regclass('storage.objects') IS NULL
       OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'hiring-files' AND o.name = v_path) THEN
      RAISE EXCEPTION 'Attach the file again.';
    END IF;
    v_file := left(coalesce(v_file, 'Job description'), 200);
  ELSE
    v_file := NULL;
  END IF;
  EXECUTE 'SELECT public.hiring_file_guest_request($1, $2, $3, $4, $5, $6, $7)'
    INTO v_id
    USING v_sub.name, NULL::text, v_name, NULL::text, coalesce(p_answers, '{}'::jsonb), v_path, v_file;
  UPDATE public.hiring_requests SET requester_sub_id = v_sub.id WHERE id = v_id;
  RETURN jsonb_build_object('id', v_id, 'position', coalesce(nullif(btrim(p_answers ->> 'position'), ''), 'the role'));
END
$function$

CREATE OR REPLACE FUNCTION public.hr_documentation_files_removed(p_paths text[])
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_docs integer;
  v_letters integer;
BEGIN
  IF NOT public.has_any_action(ARRAY['documentation.edit']) THEN
    RAISE EXCEPTION 'Deleting files needs Documentation · Edit' USING ERRCODE = '42501';
  END IF;
  INSERT INTO public.hr_document_events (document_id, what, actor_id, actor_name, note)
  SELECT d.id, 'File deleted', auth.uid(), public.hr_doc_actor_name(), d.file_name
    FROM public.hr_documents d
   WHERE d.file_path = ANY (coalesce(p_paths, '{}'::text[])) AND d.deleted_at IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'hr-documents' AND o.name = d.file_path)
     AND NOT EXISTS (SELECT 1 FROM public.hr_document_events e WHERE e.document_id = d.id AND e.what = 'File deleted');
  GET DIAGNOSTICS v_docs = ROW_COUNT;
  INSERT INTO public.hr_letter_events (letter_id, what, actor_id, actor_name, note)
  SELECT l.id, 'File deleted', auth.uid(), public.hr_doc_actor_name(), l.file_name
    FROM public.hr_person_letters l
   WHERE l.file_path = ANY (coalesce(p_paths, '{}'::text[])) AND l.withdrawn_at IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'hr-documents' AND o.name = l.file_path)
     AND NOT EXISTS (SELECT 1 FROM public.hr_letter_events e WHERE e.letter_id = l.id AND e.what = 'File deleted');
  GET DIAGNOSTICS v_letters = ROW_COUNT;
  v_docs := v_docs + v_letters;
  UPDATE public.member_memos m SET attachment_deleted_at = now()
   WHERE m.attachment_path = ANY (coalesce(p_paths, '{}'::text[])) AND m.withdrawn_at IS NOT NULL AND m.attachment_deleted_at IS NULL
     AND NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'hr-documents' AND o.name = m.attachment_path);
  GET DIAGNOSTICS v_letters = ROW_COUNT;
  v_docs := v_docs + v_letters;
  INSERT INTO public.hr_drive_file_events (file_id, what, actor_id, actor_name, note)
  SELECT f.id, 'File deleted', auth.uid(), public.hr_doc_actor_name(), f.file_name
    FROM public.hr_drive_files f
   WHERE f.file_path = ANY (coalesce(p_paths, '{}'::text[])) AND f.deleted_at IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'hr-documents' AND o.name = f.file_path)
     AND NOT EXISTS (SELECT 1 FROM public.hr_drive_file_events e WHERE e.file_id = f.id AND e.what = 'File deleted');
  GET DIAGNOSTICS v_letters = ROW_COUNT;
  RETURN v_docs + v_letters;
END
$function$

CREATE OR REPLACE FUNCTION public.it_request_file_in(p_request uuid, p_note uuid, p_files jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me   uuid := auth.uid();
  v_f    jsonb;
  v_path text;
  v_size bigint;
  v_type text;
  v_n    integer := 0;
BEGIN
  PERFORM public.it_request_files_check(p_files);
  IF p_files IS NULL OR jsonb_typeof(p_files) <> 'array' THEN
    RETURN 0;
  END IF;
  FOR v_f IN SELECT value FROM jsonb_array_elements(p_files) LOOP
    v_path := v_f ->> 'path';
    -- What the bucket says it is, before what the browser said.
    SELECT CASE WHEN (o.metadata ->> 'size') ~ '^[0-9]{1,15}$' THEN (o.metadata ->> 'size')::bigint END, nullif(o.metadata ->> 'mimetype', '')
      INTO v_size, v_type
      FROM storage.objects o WHERE o.bucket_id = 'it-requests' AND o.name = v_path;
    INSERT INTO public.it_request_files (request_id, note_id, path, name, content_type, size, uploaded_by)
    VALUES (p_request, p_note, v_path,
            left(coalesce(nullif(btrim(v_f ->> 'name'), ''), 'file'), 200),
            left(coalesce(v_type, nullif(btrim(v_f ->> 'contentType'), '')), 120),
            coalesce(v_size, CASE WHEN (v_f ->> 'size') ~ '^[0-9]{1,15}$' THEN (v_f ->> 'size')::bigint END),
            v_me);
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END
$function$

CREATE OR REPLACE FUNCTION public.it_request_files_check(p_files jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me   uuid := auth.uid();
  v_f    jsonb;
  v_path text;
BEGIN
  IF p_files IS NULL OR jsonb_typeof(p_files) <> 'array' OR jsonb_array_length(p_files) = 0 THEN
    RETURN;
  END IF;
  IF jsonb_array_length(p_files) > 10 THEN
    RAISE EXCEPTION 'Attach up to 10 files at a time.' USING ERRCODE = '22023';
  END IF;
  IF (SELECT count(DISTINCT f.value ->> 'path') FROM jsonb_array_elements(p_files) f) < jsonb_array_length(p_files) THEN
    RAISE EXCEPTION 'The same file is there twice — remove one.' USING ERRCODE = '22023';
  END IF;
  FOR v_f IN SELECT value FROM jsonb_array_elements(p_files) LOOP
    v_path := v_f ->> 'path';
    IF v_me IS NULL OR v_path IS NULL OR split_part(v_path, '/', 1) <> v_me::text OR strpos(v_path, '..') > 0
       OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'it-requests' AND o.name = v_path) THEN
      RAISE EXCEPTION 'A file did not finish uploading — add it again.' USING ERRCODE = '22023';
    END IF;
    IF EXISTS (SELECT 1 FROM public.it_request_files f WHERE f.path = v_path) THEN
      RAISE EXCEPTION 'That file is on a request already — add it again.' USING ERRCODE = '22023';
    END IF;
  END LOOP;
END
$function$

CREATE OR REPLACE FUNCTION public.member_submit_request(p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_staff uuid:=public.member_staff_id(); r public.member_requests%ROWTYPE; v_claim uuid; v_name text; v_dept uuid; v_path text; v_desc text;
BEGIN
  PERFORM public.member_send_guard((SELECT mr.kind FROM public.member_requests mr WHERE mr.id = p_request));
 IF NOT public.has_perm('member_requests') THEN RAISE EXCEPTION 'Request access is not enabled' USING ERRCODE='42501'; END IF;
 SELECT * INTO r FROM public.member_requests WHERE id=p_request AND created_by=auth.uid() AND staff_id=v_staff FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Request not found' USING ERRCODE='42501'; END IF;
 IF r.status<>'draft' THEN RETURN public.member_request_json(r.id); END IF;
 IF r.kind='claim' THEN
 -- Attachment metadata can only be attested by the server after inspecting its bytes.
 SELECT a.object_path INTO v_path FROM public.member_request_attachments a JOIN storage.objects o ON o.bucket_id='member-invoices' AND o.name=a.object_path
 WHERE a.request_id=r.id AND a.uploaded_by=auth.uid() AND a.content_sha256=r.detail->>'invoiceHash' ORDER BY a.created_at DESC LIMIT 1;
 -- An outstation claim by road is paid by the fixed rate, with no invoice; a plane ticket has one (2026-10-06).
 IF v_path IS NULL AND (coalesce(r.detail->>'claimType','') NOT IN ('outstation','food') OR coalesce((r.detail->>'planeTicket')::boolean,false)) THEN
  RAISE EXCEPTION 'A verified invoice is required before submitting';
 END IF;
 PERFORM public.member_food_claim_check(r.id);
 SELECT employee_name,department_id INTO v_name,v_dept FROM public.hr_staff_costs WHERE id=v_staff;
 v_desc:=CASE
  WHEN r.detail->>'claimType'='food' THEN public.member_food_claim_line(r.detail)
  WHEN r.detail->>'claimType'='outstation' AND coalesce((r.detail->>'planeTicket')::boolean,false) THEN
   concat('Plane ticket · ',r.detail->>'base',' → ',r.detail->>'regionName',' · ',r.detail->>'location',' (week of ',r.detail->>'week',')')
  WHEN r.detail->>'claimType'='outstation' THEN
   concat('Outstation · ',r.detail->>'base',' → ',r.detail->>'regionName',' · ',r.detail->>'spots',' spots × RM ',r.detail->>'rate',
   ' · ',r.detail->>'location',' (week of ',r.detail->>'week',')')
  WHEN r.detail->>'claimType'='airbnb' AND coalesce((r.detail->>'group')::boolean,false) THEN
   concat('Airbnb · ',r.detail->>'pax',' pax × ',r.detail->>'nights',' nights · invoice RM ',r.detail->>'invoiceAmount',
   ', up to RM ',r.detail->>'rate',' a night · ',r.detail->>'location','; ',r.detail->>'start',' — ',r.detail->>'end')
  WHEN r.detail->>'claimType'='airbnb' AND r.detail ? 'invoiceAmount' THEN
   concat('Airbnb · ',r.detail->>'pax',' pax × ',r.detail->>'nights',' nights · invoice RM ',r.detail->>'invoiceAmount',
   ', up to RM ',r.detail->>'rate',' a pax a night · ',r.detail->>'location','; ',r.detail->>'start',' — ',r.detail->>'end')
  WHEN r.detail->>'claimType'='airbnb' THEN
   concat('Airbnb · ',r.detail->>'pax',' pax × ',r.detail->>'nights',' nights × RM ',r.detail->>'rate',
   ' · ',r.detail->>'location','; ',r.detail->>'start',' — ',r.detail->>'end')
  ELSE concat(r.detail->>'category',': ',r.detail->>'location','; ',r.detail->>'start',' — ',r.detail->>'end') END;
 IF r.claim_id IS NULL THEN
 INSERT INTO public.claims(claim_type,claimant_name,department_id,amount,description,receipt_url,status,source_pool,created_by)
 VALUES('benefit',v_name,v_dept,(r.detail->>'amount')::numeric,v_desc,
 CASE WHEN v_path IS NULL THEN NULL ELSE 'member-invoices/'||v_path END,'pending','venture_pool',auth.uid()) RETURNING id INTO v_claim;
 ELSE
 UPDATE public.claims SET amount=(r.detail->>'amount')::numeric,
 description=v_desc,
 receipt_url=CASE WHEN v_path IS NULL THEN NULL ELSE 'member-invoices/'||v_path END
 WHERE id=r.claim_id AND created_by=auth.uid() AND status='pending' RETURNING id INTO v_claim;
 IF v_claim IS NULL THEN RAISE EXCEPTION 'Claim has already been reviewed; its approved amount and invoice cannot be changed'; END IF;
 END IF;
 END IF;
 IF r.kind='waiting' AND coalesce((SELECT f.require_upload FROM public.member_waiting_forms f ORDER BY f.version DESC LIMIT 1),false)
 AND NOT EXISTS(SELECT 1 FROM public.member_request_attachments a JOIN storage.objects o ON o.bucket_id='member-invoices' AND o.name=a.object_path
  WHERE a.request_id=r.id AND a.uploaded_by=auth.uid() AND a.content_sha256=r.detail->>'signedFormHash') THEN
  RAISE EXCEPTION 'Upload the signed application form before sending';
 END IF;
 IF r.kind='replacement' AND coalesce((SELECT f.require_upload FROM public.member_replacement_forms f ORDER BY f.version DESC LIMIT 1),false)
 AND NOT EXISTS(SELECT 1 FROM public.member_request_attachments a JOIN storage.objects o ON o.bucket_id='member-invoices' AND o.name=a.object_path
  WHERE a.request_id=r.id AND a.uploaded_by=auth.uid() AND a.content_sha256=r.detail->>'signedFormHash') THEN
  RAISE EXCEPTION 'Upload the signed replacement form before sending';
 END IF;
 UPDATE public.member_requests SET status='submitted',submitted_at=now(),claim_id=v_claim WHERE id=r.id;
 RETURN public.member_request_json(r.id);
END $function$

CREATE OR REPLACE FUNCTION public.member_waiting_add_form(p_request uuid, p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row        public.member_requests;
  v_size       bigint;
  v_mime       text;
  v_constraint text;
BEGIN
  IF public.member_is_manager('member_requests_manage') IS NOT TRUE
     OR public.has_any_action(ARRAY['member.manage']) IS NOT TRUE THEN
    RAISE EXCEPTION 'HR management access is required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM public.member_requests WHERE id = p_request FOR UPDATE;
  IF NOT FOUND OR v_row.created_by IS DISTINCT FROM auth.uid() OR v_row.kind IS DISTINCT FROM 'waiting'
     OR v_row.status IS DISTINCT FROM 'draft' OR v_row.detail ->> 'addedBy' IS DISTINCT FROM 'hr'
     OR coalesce(v_row.detail ->> 'signedFormHash', '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'This addition is no longer waiting for its form. Close the window and look at the list.' USING ERRCODE = '22023';
  END IF;
  IF p_path IS NULL OR p_path !~ ('^' || auth.uid()::text || '/' || p_request::text || '/[0-9a-f-]{36}\.(pdf|png|jpg|docx|doc)$') THEN
    RAISE EXCEPTION 'Attach the signed application form again' USING ERRCODE = '22023';
  END IF;
  IF to_regclass('storage.objects') IS NULL THEN
    RAISE EXCEPTION 'Attach the signed application form again' USING ERRCODE = '22023';
  END IF;
  EXECUTE 'SELECT (o.metadata ->> ''size'')::bigint, o.metadata ->> ''mimetype'' FROM storage.objects o
            WHERE o.bucket_id = ''member-invoices'' AND o.name = $1'
     INTO v_size, v_mime USING p_path;
  IF v_size IS NULL OR v_size < 1 OR v_size > 3145728 OR v_mime IS NULL
     OR v_mime NOT IN ('application/pdf', 'image/png', 'image/jpeg', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword') THEN
    RAISE EXCEPTION 'Attach the signed application form again' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.member_request_attachments (request_id, uploaded_by, object_path, mime_type, size_bytes, content_sha256)
  VALUES (v_row.id, auth.uid(), p_path, v_mime, v_size, v_row.detail ->> 'signedFormHash');
  BEGIN
    UPDATE public.member_requests
       SET status = 'waiting', submitted_at = now(), reviewed_by = auth.uid(), reviewed_at = now(), note = 'Added on Sales Groups'
     WHERE id = v_row.id
    RETURNING * INTO v_row;
  EXCEPTION WHEN unique_violation THEN
    GET STACKED DIAGNOSTICS v_constraint = CONSTRAINT_NAME;
    IF v_constraint = 'member_waiting_unique_contact' THEN
      RAISE EXCEPTION 'This phone number is already on the waiting list, or waiting for review in Member services' USING ERRCODE = '22023';
    END IF;
    RAISE;
  END;
  RETURN jsonb_build_object('id', v_row.id, 'requestNo', v_row.request_no, 'status', v_row.status);
END
$function$

CREATE OR REPLACE FUNCTION public.member_waiting_attach_form(p_request uuid, p_path text, p_name text, p_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row  public.member_requests;
  v_name text := left(btrim(coalesce(p_name, '')), 200);
  v_size bigint;
  v_mime text;
  v_at   timestamptz;
BEGIN
  IF public.member_is_manager('member_requests_manage') IS NOT TRUE
     OR public.has_any_action(ARRAY['member.manage']) IS NOT TRUE THEN
    RAISE EXCEPTION 'HR management access is required' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO v_row FROM public.member_requests WHERE id = p_request FOR UPDATE;
  IF NOT FOUND OR v_row.kind IS DISTINCT FROM 'waiting'
     OR coalesce(v_row.status, '') NOT IN ('waiting', 'reserved', 'accepted') THEN
    RAISE EXCEPTION 'This applicant is no longer on the waiting list. Reload the page.' USING ERRCODE = '22023';
  END IF;
  IF v_name = '' OR coalesce(p_hash, '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'Attach the signed form again' USING ERRCODE = '22023';
  END IF;
  IF p_path IS NULL OR p_path !~ ('^' || auth.uid()::text || '/' || p_request::text || '/[0-9a-f-]{36}\.(pdf|png|jpg|docx|doc)$') THEN
    RAISE EXCEPTION 'Attach the signed form again' USING ERRCODE = '22023';
  END IF;
  IF v_row.detail ->> 'signedFormHash' IS NOT DISTINCT FROM p_hash
     AND EXISTS (SELECT 1 FROM public.member_request_attachments a WHERE a.request_id = v_row.id AND a.content_sha256 = p_hash) THEN
    RAISE EXCEPTION 'This file is already their signed form' USING ERRCODE = '22023';
  END IF;
  IF to_regclass('storage.objects') IS NULL THEN
    RAISE EXCEPTION 'Attach the signed form again' USING ERRCODE = '22023';
  END IF;
  EXECUTE 'SELECT (o.metadata ->> ''size'')::bigint, o.metadata ->> ''mimetype'' FROM storage.objects o
            WHERE o.bucket_id = ''member-invoices'' AND o.name = $1'
     INTO v_size, v_mime USING p_path;
  IF v_size IS NULL OR v_size < 1 OR v_size > 3145728 OR v_mime IS NULL
     OR v_mime NOT IN ('application/pdf', 'image/png', 'image/jpeg', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', 'application/msword')
     OR substring(p_path FROM '\.([a-z]+)$') IS DISTINCT FROM (CASE v_mime WHEN 'application/pdf' THEN 'pdf' WHEN 'image/png' THEN 'png' WHEN 'image/jpeg' THEN 'jpg' WHEN 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' THEN 'docx' WHEN 'application/msword' THEN 'doc' END) THEN
    RAISE EXCEPTION 'Attach the signed form again' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.member_request_attachments (request_id, uploaded_by, object_path, mime_type, size_bytes, content_sha256)
  VALUES (v_row.id, auth.uid(), p_path, v_mime, v_size, p_hash)
  RETURNING created_at INTO v_at;
  UPDATE public.member_requests
     SET detail = detail || jsonb_build_object('signedFormName', v_name, 'signedFormHash', p_hash)
   WHERE id = v_row.id;
  INSERT INTO public.member_request_events (request_id, actor_id, from_status, to_status, note)
  VALUES (v_row.id, auth.uid(), v_row.status, v_row.status, 'Signed form uploaded · ' || v_name);
  RETURN jsonb_build_object(
    'name', v_name,
    'type', v_mime,
    'at', v_at,
    'by', coalesce(
      (SELECT s.employee_name FROM public.hr_staff_costs s WHERE s.user_id = auth.uid() ORDER BY s.status = 'active' DESC LIMIT 1),
      (SELECT CASE u.role::text WHEN 'hr' THEN 'HR' WHEN 'principal' THEN 'Principal' WHEN 'finance' THEN 'Finance' ELSE initcap(replace(u.role::text, '_', ' ')) END
         FROM public.users u WHERE u.id = auth.uid())
    )
  );
END
$function$

CREATE OR REPLACE FUNCTION public.my_photo_set(p_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me uuid := public.att_my_staff_id();
BEGIN
  IF v_me IS NULL THEN RAISE EXCEPTION 'A photo needs a staff record linked to this login.' USING ERRCODE = '42501'; END IF;
  IF p_path IS NULL OR NOT starts_with(p_path, 'profile/' || auth.uid()::text || '/') OR strpos(p_path, '..') > 0
     OR NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'attendance' AND o.name = p_path) THEN
    RAISE EXCEPTION 'The photo was not filed — choose it again.' USING ERRCODE = '22023';
  END IF;
  UPDATE public.hr_staff_costs SET photo_path = p_path WHERE id = v_me;
  RETURN jsonb_build_object('path', p_path);
END
$function$
